// Map each merged item into a simplified object with title and link
const combinedItems = items.map(item => {
  return {
    json: {
      title: item.json.title || item.json.description || "(No title)",
      link: item.json.link || item.json.guid || "",
      summary: item.json.contentSnippet || item.json.summary || ""
    }
  };
});

return combinedItems;

// Combine all RSS posts into one text block
const combined = items.map(item => {
  const title = item.json.title || "Untitled";
  const summary = item.json.summary || "";
  const link = item.json.link || "";
  return `• ${title}\n${summary}\n${link}\n`;
}).join("\n");

return [
  {
    json: {
      mergedFeedText: combined,
      totalArticles: items.length
    }
  }
];

// Parse the AI agent's JSON string output into proper JSON objects
const aiOutput = $input.first().json.output;

// Remove any markdown code block formatting
let cleanedOutput = aiOutput
  .replace(/```json\n?/g, '')
  .replace(/```\n?/g, '')
  .replace(/^\s*\[?\n/g, '[')
  .replace(/\n\]?\s*$/g, ']')
  .trim();

// Parse the JSON string
const parsedStories = JSON.parse(cleanedOutput);

// Return the parsed stories as separate items with proper structure
return parsedStories.map(story => ({
  json: {
    title: story.title,
    summary: story.summary,
    link: story.link
  }
}));

// Combine all 10 stories into a single JSON array
const allStories = $input.all().map(item => item.json);

return [{
  json: {
    totalStories: allStories.length,
    stories: allStories
  }
}];

