// Get all 4 QA responses from Merge1
const allResponses = $input.all();
const qaResults = allResponses.map(item => item.json);

// Check decisions
const anyVeto = qaResults.some(qa => qa.decision === "VETO");
const allApprove = qaResults.every(qa => qa.decision === "APPROVE");

// Collect vetoed agents
const vetoedAgents = qaResults
  .filter(qa => qa.decision === "VETO")
  .map(qa => ({
    decision: qa.decision,
    veto_reason: qa.veto_reason || null,
    suggestions: qa.suggestions || []
  }));

// Get the ORIGINAL data that was sent TO the QA agents
// Use $() to reference Code in JavaScript4 which sent the data
const originalInput = $('Code in JavaScript4').last().json;

return [{
  json: {
    anyVeto: anyVeto,
    allApprove: allApprove,
    vetoCount: vetoedAgents.length,
    vetoedAgents: vetoedAgents,
    allQAResults: qaResults,
    originalPost: originalInput.post,
    selectedStory: originalInput.selectedStory,
    revisionCount: originalInput.revisionCount || 0  // Get from Code JS4
  }
}];

// Get the data
const data = $json;

// Build a prompt with all veto reasons and suggestions
const vetoedAgents = data.vetoedAgents || [];

const rewritePrompt = `
The following QA agents have VETOED the post. Please rewrite it to address ALL their concerns:

${vetoedAgents.map((agent, i) => `
Agent ${i+1} Veto Reason: ${agent.veto_reason}
Suggestions: ${agent.suggestions.join(', ')}
`).join('\n')}

Original Post: ${data.originalPost || 'See previous data'}

Rewrite the post to address all concerns while maintaining the brand voice.
`;

return [{
  json: {
    rewritePrompt: rewritePrompt,
    vetoCount: vetoedAgents.length,
    originalData: data
  }
}];

// Get the AI output
let rawOutput = $json.output || $json.message || $json.text;

// Remove markdown code blocks
rawOutput = rawOutput.replace(/```json\n/g, '').replace(/```/g, '').trim();

// Parse the JSON
const rewrittenData = JSON.parse(rawOutput);

// Check revision count - max 3 loops
if (rewrittenData.revisionCount > 3) {
  return [{
    json: {
      error: "Maximum revisions reached (3 attempts)",
      requiresManualReview: true,
      finalPost: rewrittenData.post,
      selectedStory: rewrittenData.selectedStory
    }
  }];
}

// Return the rewritten post in the same format as Code in JavaScript4
return [{
  json: {
    selectedStory: rewrittenData.selectedStory,
    post: rewrittenData.post,
    revisionCount: rewrittenData.revisionCount,
    changesApplied: rewrittenData.changesApplied,
    // Include all the other fields that the QA agents expect
    platform: "multi-platform"
  }
}];

