// Parse the JSON
const purpleCowAnalysis = JSON.parse(rawOutput);

// Get the original data
const originalPost = $('If1').item.json.originalPost;
const originalTitle = $('If1').item.json.selectedStory;

return [{
  json: {
    originalPost: originalPost,
    originalTitle: originalTitle,
    purpleCowSuggestions: purpleCowAnalysis,
    hookSuggestions: purpleCowAnalysis.hook.suggestions,
    shareabilitySuggestions: purpleCowAnalysis.shareability.suggestions,
    memorabilitySuggestions: purpleCowAnalysis.memorability.suggestions,
    authenticitySuggestions: purpleCowAnalysis.authenticity.suggestions,
    proposedTitle: purpleCowAnalysis.title.proposedTitle,
    titleAlternatives: purpleCowAnalysis.title.alternatives
  }
}];

// Get the AI output
let rawOutput = $json.output || $json.message || $json.text;

// Remove markdown code blocks if present
rawOutput = rawOutput.replace(/```json\n/g, '').replace(/```/g, '').trim();

// Parse the JSON
let polishedData;
try {
  polishedData = JSON.parse(rawOutput);
} catch (error) {
  return [{
    json: {
      error: "Failed to parse Polish Agent output as JSON",
      rawOutput: rawOutput,
      parseError: error.message
    }
  }];
}

// Get the original approved version from If1
const approvedPost = $('If1').item.json.originalPost;
const approvedTitle = $('If1').item.json.selectedStory;

// Extract blog post
const blogPost = polishedData.blogPost || {};

// Extract social media versions
const socialMedia = polishedData.socialMedia || {};
const facebook = socialMedia.facebook || {};
const instagram = socialMedia.instagram || {};
const linkedin = socialMedia.linkedin || {};
const twitter = socialMedia.twitter || {};

// Format the output with all versions
return [{
  json: {
    // Original approved 8/10 version
    approved_title: approvedTitle,
    approved_post: approvedPost,
    approved_version: "8/10",

    // New polished 10/10 blog post version
    polished_title: blogPost.title || polishedData.title,
    polished_post: blogPost.content || polishedData.polishedPost,
    polished_version: blogPost.version || "10/10",
    polished_word_count: blogPost.wordCount || 0,

    // Social media versions
    facebook_post: facebook.post || "",
    facebook_char_count: facebook.characterCount || 0,
    facebook_has_link: facebook.includesLink || false,

    instagram_caption: instagram.caption || "",
    instagram_char_count: instagram.characterCount || 0,
    instagram_hashtags: instagram.hashtags || [],
    instagram_visual_suggestion: instagram.visualSuggestion || "",
    instagram_cta: instagram.callToAction || "Link in bio",

    linkedin_post: linkedin.post || "",
    linkedin_char_count: linkedin.characterCount || 0,
    linkedin_hashtags: linkedin.hashtags || [],

    twitter_thread: twitter.thread || [],
    twitter_char_counts: twitter.characterCounts || [],
    twitter_tweet_count: (twitter.thread || []).length,

    // Metadata
    changes_applied: polishedData.changesApplied || [],

    // Both versions for comparison
    versions: {
      approved: {
        title: approvedTitle,
        post: approvedPost,
        version: "8/10"
      },
      polished: {
        title: blogPost.title || polishedData.title,
        post: blogPost.content || polishedData.polishedPost,
        version: "10/10",
        wordCount: blogPost.wordCount || 0
      }
    },

    // All social media in one object for easy access
    social: {
      facebook: {
        post: facebook.post || "",
        charCount: facebook.characterCount || 0,
        hasLink: facebook.includesLink || false
      },
      instagram: {
        caption: instagram.caption || "",
        charCount: instagram.characterCount || 0,
        hashtags: instagram.hashtags || [],
        visual: instagram.visualSuggestion || "",
        cta: instagram.callToAction || "Link in bio"
      },
      linkedin: {
        post: linkedin.post || "",
        charCount: linkedin.characterCount || 0,
        hashtags: linkedin.hashtags || []
      },
      twitter: {
        thread: twitter.thread || [],
        charCounts: twitter.characterCounts || [],
        tweetCount: (twitter.thread || []).length
      }
    }
  }
}];
